import{_ as n,l as r,o as t,c as p,v as e,p as l,x as o,d as h,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"矩阵链与 Knuth 优化","description":"","frontmatter":{"title":"矩阵链与 Knuth 优化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/knuth-opt-matrix-chain.md","filePath":"cs/knuth-opt-matrix-chain.md","lastUpdated":1789023840000}'),u={name:"cs/knuth-opt-matrix-chain.md"};function c(_,a,m,P,k,f){const i=r("Mermaid");return t(),p("div",null,[a[1]||(a[1]=e('<h1 id="矩阵链与-knuth-优化" tabindex="-1">矩阵链与 Knuth 优化 <a class="header-anchor" href="#矩阵链与-knuth-优化" aria-label="Permalink to &quot;矩阵链与 Knuth 优化&quot;">​</a></h1><div class="epigraph"><p>矩阵链乘法的最优加括号是区间 DP；Knuth 的 $opt$ 单调把切点枚举从 $O(n)$ 收到均摊 $O(1)$，总 $O(n^2)$。</p><footer>—— 据 Godbole, 1973；Knuth, 1971；Yao, 1980；CLRS 第 15.2 节整理</footer></div><p>上一课<a href="/cs/optimal-bst">最优二叉搜索树</a>已用 Knuth 单调。主干<a href="/cs/interval-dp">区间 DP</a>写过矩阵链 \\(O(n^3)\\)。缺口是把 Knuth 优化钉在矩阵链（及满足四边形的同类）上，作为 DP 进阶课序收束。不重写 \\(dp[i][j]=\\min_k dp[i][k]+dp[k+1][j]+p_{i-1}p_k p_j\\)。下一单元字符串 Z 函数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>切点 \\(opt[i][j]\\) 对矩阵链满足 \\(opt[i][j-1]\\le opt[i][j]\\le opt[i+1][j]\\)（在代价满足四边形时）。填 \\(j-i\\) 递增时，\\(k\\) 只扫这段，$ \\sum(opt[i][j]-opt[i][j-1])$ 均摊使总 \\(O(n^2)\\)。</p><p>缺口是范围收缩，不是 Strassen 的块乘。矩阵链优化的是<strong>加括号次数代价</strong>，每个 \\(\\times\\) 仍是普通矩阵乘。</p><h3 id="不是所有区间-dp-都能-knuth" tabindex="-1">不是所有区间 DP 都能 Knuth <a class="header-anchor" href="#不是所有区间-dp-都能-knuth" aria-label="Permalink to &quot;不是所有区间 DP 都能 Knuth&quot;">​</a></h3><p>石子合并若代价不满足四边形就不能。先验证 \\(w(i,j)+w[i&#39;,j&#39;]\\le w(i,j&#39;)+w(i&#39;,j)\\) 一类。不会证就留 \\(O(n^3)\\) 或用分治优化（更弱条件）。</p><p><span class="marginnote">CLRS 15.2 矩阵链。Knuth 原为 BST。Yao 推广。后课 Z 函数离开 DP。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准区间 DP 框架，<code>k</code> 从 <code>opt[i][j-1]</code> 到 <code>opt[i+1][j]</code>。存 \\(opt\\)。对照 BST 同一循环。</p>',11)),(t(),l(d,null,{default:o(()=>[s(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22w%20%E5%9B%9B%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20OPT%5B%22opt%5Bi%5D%5Bj%5D%20%E5%A4%B9%E9%80%BC%22%5D%0A%20%20OPT%20--%3E%20N2%5B%22%E5%8C%BA%E9%97%B4%20DP%20O(n%5E2)%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>输出加括号方案用 \\(opt\\) 递归。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>更长区间的最优切点夹在较短区间切点之间，故枚举不回头。与 SMAWK：Knuth 针对二维区间表的 \\(opt\\) 二维单调；SMAWK 针对一层 \\(i\\)–\\(j\\) 矩阵。与 CHT：结构不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写高精度矩阵代价。不写并行加括号。DP 进阶到此：后课默认区间 DP 先看四边形/Knuth/分治/CHT。下一课 Z 函数，串算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>矩阵链代价区间 DP；Knuth 收 \\(O(n^2)\\)。</li><li>条件是四边形 + \\(opt\\) 夹逼。</li><li>优化括号不是优化一次矩阵乘的 \\(\\omega\\)。</li><li>出处：Godbole, 1973；Knuth, 1971；Yao, 1980；CLRS 第 15.2 节。</li></ul>',7))])}const B=n(u,[["render",c]]);export{T as __pageData,B as default};
